def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)

    # The legend uses the most common background color in alternating columns.
    background = counts.most_common(1)[0][0]
    key_row = max(
        range(h),
        key=lambda r: sum(
            (grid[r][c] == background) if c % 2 == 0
            else (grid[r][c] != background)
            for c in range(w)
        )
    )
    sequence = [
        grid[key_row][c] for c in range(1, w, 2)
        if grid[key_row][c] != background
    ]
    if len(sequence) < 2:
        return [row[:] for row in grid]

    # Locate the colored 2x2 tiles.
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            color = grid[r][c]
            if color in sequence and all(
                grid[rr][cc] == color
                for rr in (r, r + 1) for cc in (c, c + 1)
            ):
                tiles.append((r, c, color))

    row_values = sorted({t[0] for t in tiles})
    col_values = sorted({t[1] for t in tiles})
    row_rank = {v: i for i, v in enumerate(row_values)}
    col_rank = {v: i for i, v in enumerate(col_values)}

    def neighbors(i, j):
        r, c, _ = tiles[i]
        rr, cc, _ = tiles[j]
        return abs(row_rank[r] - row_rank[rr]) + abs(col_rank[c] - col_rank[cc]) == 1

    # Order tiles along the legend's color sequence.
    path, used = [], set()

    def find_path(pos):
        if pos == len(sequence):
            return True
        for i, (_, _, color) in enumerate(tiles):
            if i in used or color != sequence[pos]:
                continue
            if path and not neighbors(path[-1], i):
                continue
            used.add(i)
            path.append(i)
            if find_path(pos + 1):
                return True
            path.pop()
            used.remove(i)
        return False

    find_path(0)
    out = [row[:] for row in grid]

    # Each tile extends its own color through the gap toward the next tile.
    for a, b in zip(path, path[1:]):
        r, c, color = tiles[a]
        nr, nc, _ = tiles[b]
        if r == nr:
            for rr in (r, r + 1):
                for cc in range(min(c, nc) + 2, max(c, nc)):
                    if grid[rr][cc] == background:
                        out[rr][cc] = color
        elif c == nc:
            for rr in range(min(r, nr) + 2, max(r, nr)):
                for cc in (c, c + 1):
                    if grid[rr][cc] == background:
                        out[rr][cc] = color

    return out
